  "title": "fix-int-serialization-in-eventserializer",
  "request": "hey, the EventSerializer seems to keep huge ints as numbers, which breaks JS clients. can you make it convert ints outside the JS safe range to strings? also keep bools as bools.",
  "edits": [
    {
      "path": "langfuse/_utils/serializer.py",
      "search": "    def is_js_safe_integer(value: int) -> bool:",
      "replace": "    def is_js_safe_integer(value: int) -> bool:
        """
        Determines whether an integer can be safely represented in JavaScript
        without loss of precision. JavaScript numbers are safe up to 2**53 - 1.
        Booleans are subclasses of int but should be considered safe.
        """
        if isinstance(value, bool):
            return True
        # JavaScript safe integer range: -(2**53 - 1) to 2**53 - 1
        max_safe = (1 << 53) - 1
        return -max_safe <= value <= max_safe"
    }
  ],
  "test_path": "tests/unit/test_event_serializer_int.py",
  "test": "import pytest
from langfuse._utils.serializer import EventSerializer

@pytest.fixture
def serializer():
    return EventSerializer()

def test_small_int_is_kept_as_int(serializer):
    val = serializer.default(42)
    assert isinstance(val, int)
    assert val == 42

def test_large_int_is_serialized_as_string(serializer):
    large = 2 ** 60
    val = serializer.default(large)
    assert isinstance(val, str)
    assert val == str(large)

def test_bool_is_kept_as_bool(serializer):
    assert serializer.default(True) is True
    assert serializer.default(False) is False"
}
